// বিসিএস MCQ — english.js
var data_english = [{"id":"english-1","exam":"৩৬তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"The plural form of 'datum' is—","options":["datums","data","datas","datum"],"correctIndex":1,"explanation":"The plural form of 'datum' is 'data'. It is a Latin word and follows Latin plural rules."},{"id":"english-2","exam":"৩৬তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"Choose the correct sentence:","options":["He is more taller than his brother","He is taller than his brother","He is the more tall than his brother","He is tallest than his brother"],"correctIndex":1,"explanation":"In comparative degree, we use 'taller than' not 'more taller than'. The correct sentence is 'He is taller than his brother.'"},{"id":"english-3","exam":"৩৫তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"The synonym of 'ephemeral' is—","options":["permanent","transitory","everlasting","eternal"],"correctIndex":1,"explanation":"'Ephemeral' means lasting for a very short time. Its synonym is 'transitory' which also means short-lived or temporary."},{"id":"english-4","exam":"৩৫তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"The passive form of 'People speak English all over the world' is—","options":["English is spoken all over the world","English was spoken all over the world","English has been spoken all over the world","English will be spoken all over the world"],"correctIndex":0,"explanation":"The passive voice of present simple tense is: Subject + is/am/are + past participle. So 'English is spoken all over the world' is correct."},{"id":"english-5","exam":"৩৪তম বিসিএস","subject":"ইংরেজি","topic":"Literature","question":"Who wrote 'Paradise Lost'?","options":["William Shakespeare","John Milton","John Keats","William Wordsworth"],"correctIndex":1,"explanation":"'Paradise Lost' is an epic poem written by John Milton in 1667. It tells the biblical story of the Fall of Man."},{"id":"english-6","exam":"৩৪তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"'He said, \"I am reading a book.\"' The indirect speech is—","options":["He said that he was reading a book","He said that he is reading a book","He said that I was reading a book","He told he was reading a book"],"correctIndex":0,"explanation":"In indirect speech, the present continuous tense (am/is/are + verb-ing) changes to past continuous (was/were + verb-ing). Pronoun 'I' changes to 'he'."},{"id":"english-7","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"The antonym of 'benevolent' is—","options":["malevolent","kind","generous","charitable"],"correctIndex":0,"explanation":"'Benevolent' means well-meaning and kindly. Its antonym is 'malevolent' which means having or showing a wish to do evil to others."},{"id":"english-8","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"The correct spelling is—","options":["accomodation","accommodation","acomodation","acommodation"],"correctIndex":1,"explanation":"The correct spelling is 'accommodation' with double 'c' and double 'm'."},{"id":"english-9","exam":"৩২তম বিসিএস","subject":"ইংরেজি","topic":"Idioms","question":"'A man of straw' means—","options":["a strong man","a weak or poor man","a tall man","a brave man"],"correctIndex":1,"explanation":"'A man of straw' is an idiom that means a weak, poor, or insignificant person."},{"id":"english-10","exam":"৩২তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"Which sentence is correct?","options":["Neither he nor I is wrong","Neither he nor I are wrong","Neither he nor I was wrong","Neither he nor I were wrong"],"correctIndex":2,"explanation":"With 'neither...nor', the verb agrees with the nearest subject. Since 'I' is the nearest subject and the sentence refers to past, 'was' is used."},{"id":"english-11","exam":"৩১তম বিসিএস","subject":"ইংরেজি","topic":"Literature","question":"'To be or not to be' is from—","options":["Macbeth","Hamlet","Othello","King Lear"],"correctIndex":1,"explanation":"'To be, or not to be, that is the question' is the opening line of a soliloquy in Act 3, Scene 1 of Shakespeare's play 'Hamlet'."},{"id":"english-12","exam":"৩১তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"Choose the correct preposition: She is good ___ mathematics.","options":["in","at","for","with"],"correctIndex":1,"explanation":"The correct preposition is 'at'. We say 'good at' a subject or skill. For example: 'She is good at mathematics.'"},{"id":"english-13","exam":"৩০তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"The word 'Magnanimous' means—","options":["great in courage","very generous","very angry","very famous"],"correctIndex":1,"explanation":"'Magnanimous' means very generous or forgiving, especially toward a rival or someone less powerful."},{"id":"english-14","exam":"৩০তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"The verb form of 'beauty' is—","options":["beautify","beauteous","beautiful","beautifully"],"correctIndex":0,"explanation":"The verb form of 'beauty' is 'beautify', meaning to make something beautiful."},{"id":"english-15","exam":"২৯তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"The past participle of 'broadcast' is—","options":["broadcasted","broadcast","broadcasting","broadcasts"],"correctIndex":1,"explanation":"'Broadcast' is an irregular verb. Its past tense and past participle are both 'broadcast' (not 'broadcasted')."},{"id":"english-16","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"'Helena said I took the laptop home with me.' Its indirect form is-","options":["Helena said that she took the laptop home with her","Helena said that she had taken the laptop home with her","Helena confirmed that she has taken the laptop home with her","Helena told that she had the laptop taken home with her"],"correctIndex":1,"subject":"ইংরেজি","explanation":"সঠিক উত্তর: Helena said that she had taken the laptop home with her। Assertive sentence-কে direct থেকে indirect করার সময়: inverted comma সরে 'that' বসে, subject-এর person বদলায় (I→she, me→her), আর direct speech-এর past indefinite tense (took) indirect-এ past perfect (had taken)-এ পরিবর্তিত হয়। অন্য অপশনগুলোতে এই tense পরিবর্তন সঠিকভাবে হয়নি।"},{"id":"english-17","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"'It is no good falling in love at first sight'. Here the word \"falling\" is a/an -","options":["participle","infinitive","gerund","verbal noun"],"correctIndex":2,"subject":"ইংরেজি","explanation":"'Falling' এখানে gerund (verb+ing যা noun-এর কাজ করে)। 'It is no good/use' structure-এর পর verb সবসময় gerund হয়; বাক্যের real subject আসলে 'falling in love at first sight' (rearranged: Falling in love at first sight is no good)। Present participle হলে এটি adjective-এর কাজ করত (যেমন: The falling leaves), যা এখানে হচ্ছে না।"},{"id":"english-18","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"In which of these poems did Matthew Arnold express a pessimistic worldview, reflecting on a world full of conflicts and lacking in joy, evincing an implicit criticism of Victorian era's aggressive spirit?","options":["Scholar Gipsy","Dover Beach","Rugby Chapel","Immortality"],"correctIndex":1,"subject":"ইংরেজি","explanation":"সঠিক উত্তর 'Dover Beach' (১৮৬৭, Matthew Arnold-এর সবচেয়ে বিখ্যাত কবিতা, তাঁর New Poems সংকলনে প্রকাশিত)। কবিতাটি ভিক্টোরিয়ান যুগের আধ্যাত্মিক সংকট ও ধর্মবিশ্বাসের অবক্ষয় তুলে ধরে; পৃথিবীকে দেখানো হয়েছে এক 'darkling plain' হিসেবে যেখানে মানুষ অজ্ঞাতসারে সংঘর্ষে লিপ্ত, আনন্দ-ভালোবাসা-নিশ্চয়তাবিহীন। অন্য অপশনগুলো ভিন্ন সুরের — কোনোটিতেই এই নিরাশাবাদী সংঘাত-চিত্র নেই।"},{"id":"english-19","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Idioms","question":"Candidates are required to get ______ the centre before 09:00 AM.","options":["at","to","in","into"],"correctIndex":1,"subject":"ইংরেজি","explanation":"সঠিক phrasal verb 'get to' (পৌঁছানো/arrive) — বাক্যটি হবে: Candidates are required to get to the centre before 09:00 AM (প্রার্থীদের সকাল ৯টার আগে কেন্দ্রে পৌঁছাতে হবে)।"},{"id":"english-20","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"The killing of albatross in The Rime of the Ancient Mariner was indicative of -","options":["a trigger-happy Mariner","the essential irrationality of man","a superstitious Mariner","the Mariner as a skillful fowler"],"correctIndex":1,"subject":"ইংরেজি","explanation":"Samuel Taylor Coleridge-এর 'The Rime of the Ancient Mariner' কবিতায় অ্যালবাট্রস পাখি হত্যার ঘটনাটি মানুষের অকারণ, অযৌক্তিক আচরণের (essential irrationality of man) প্রতীক — পাখিটি নাবিকদের বন্ধু ছিল, তবু বিনা কারণে Mariner সেটিকে হত্যা করে এবং তার প্রায়শ্চিত্ত করতে হয়। কবিতাটি ১৭৯৮ সালে Lyrical Ballads-এ প্রথম প্রকাশিত হয়। অন্য অপশনগুলো ভুল — Mariner-কে trigger-happy বা দক্ষ শিকারি হিসেবে দেখানো হয়নি, আর কুসংস্কারাচ্ছন্ন ছিল অন্য নাবিকরা, Mariner নিজে নয়।"},{"id":"english-21","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"Which novel chronicles intense, destructive love fueling multigenerational cruelty & obsession?","options":["Jane Eyre","Emma","Wuthering Heights","Persuasion"],"correctIndex":2,"subject":"ইংরেজি","explanation":"Emily Bronte-এর 'Wuthering Heights' (১৮৪৭, ছদ্মনাম Ellis Bell-এ প্রকাশিত) Heathcliff ও Catherine Earnshaw-এর তীব্র, ধ্বংসাত্মক প্রেম এবং তা থেকে জন্ম নেওয়া প্রজন্মব্যাপী প্রতিশোধ ও নিষ্ঠুরতার কাহিনি। এটি Emily Bronte-এর একমাত্র উপন্যাস। অন্য অপশনগুলো (Jane Eyre, Emma, Persuasion) ভিন্ন ধাঁচের — happy ending, রোমান্টিক কমেডি, বা পরিপক্ব প্রেমের গল্প, প্রজন্মব্যাপী ধ্বংসাত্মক প্রতিশোধ নেই।"},{"id":"english-22","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"Which of these is not characteristic of English Romantic Poetry?","options":["Ordinary life","Everyday language","Expression of feelings rather than action or plot","Inane and gaudy phraseology"],"correctIndex":3,"subject":"ইংরেজি","explanation":"William Wordsworth-এর 'Preface to Lyrical Ballads' (১৮০০, রোমান্টিক যুগের ম্যানিফেস্টো) অনুযায়ী রোমান্টিক কবিতার বৈশিষ্ট্য হলো সাধারণ জীবন (ordinary/rustic life), প্রতিদিনের ভাষা (language really used by men), এবং কাহিনির চেয়ে অনুভূতির স্বতঃস্ফূর্ত প্রকাশ (spontaneous overflow of powerful feelings)। 'Inane and gaudy phraseology' (অর্থহীন, চটকদার ভাষা) বরং Wordsworth যা প্রত্যাখ্যান করে রোমান্টিক যুগ শুরু করেন — তাই এটি রোমান্টিক কবিতার বৈশিষ্ট্য নয়, বরং এর বিপরীত। রোমান্টিক যুগের স্থায়িত্বকাল ১৭৯৮-১৮৩২ (৩৪ বছর), ইংরেজি সাহিত্যের সবচেয়ে সংক্ষিপ্ত যুগ।"},{"id":"english-23","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"In William Shakespeare's play As You Like It, the Seven Ages of Man speech was delivered by-","options":["Oliver","Orlando","Jaques","Rosalind"],"correctIndex":2,"subject":"ইংরেজি","explanation":"'As You Like It' নাটকের বিখ্যাত 'Seven Ages of Man' monologue ('All the world's a stage...') Act II, Scene VII-এ Jaques নামক মেলানকলিক চরিত্র দিয়ে দেয়া হয়, যিনি Duke Senior-এর সাথে Forest of Arden-এ নির্বাসিত। এই বক্তৃতায় তিনি জীবনকে সাতটি পর্যায়ে ভাগ করেন: Infant, Schoolboy, Lover, Soldier, Justice, Pantaloon, Second childishness। নাটকটি ১৫৯৮-১৬০০ সালের মধ্যে লেখা, ১৬২৩ সালে First Folio-তে প্রকাশিত।"},{"id":"english-24","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"The book that she recommended turned out to be very helpful. Here the underlined clause ('that she recommended') is a-","options":["relative clause","noun clause","adverbial clause","independent clause"],"correctIndex":0,"subject":"ইংরেজি","explanation":"'That she recommended' একটি relative (adjective) clause, কারণ এটি noun 'the book'-কে modify করছে (কোন বইয়ের কথা বলা হচ্ছে তা নির্দিষ্ট করছে)। Relative clause সাধারণত relative pronoun (that, who, whose, whom, which, when, why) দিয়ে শুরু হয় এবং noun/pronoun-এর পরে বসে তাকে modify করে। এখানে 'that' বাদ দিলেও বাক্যের অর্থ ঠিক থাকে (The book she recommended...), যা adjective clause-এর একটি বৈশিষ্ট্য।"},{"id":"english-25","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Vocabulary","question":"What is the antonym of 'percipience'?","options":["shrewdness","dullness","discerning","astuteness"],"correctIndex":1,"subject":"ইংরেজি","explanation":"'Percipience' অর্থ তীক্ষ্ণ উপলব্ধিশক্তি বা perceptiveness। এর বিপরীত শব্দ 'dullness' (নির্বুদ্ধিতা/নিষ্প্রভতা)। বাকি অপশনগুলো (shrewdness, discerning, astuteness) সবই percipience-এর কাছাকাছি অর্থের সমার্থক শব্দ, বিপরীত নয়।"},{"id":"english-26","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"Identify the sentence where 'up' functions as a noun-","options":["He turned the volume up.","Business confidence is on the up.","We live just up the road.","Our system should be up by afternoon."],"correctIndex":1,"subject":"ইংরেজি","explanation":"'Business confidence is on the up' বাক্যে 'up' noun হিসেবে ব্যবহৃত — এর আগে article 'the' আছে এবং এটি preposition 'on'-এর object, idiom 'on the up' (উন্নতির দিকে যাচ্ছে) গঠন করেছে। অন্য বাক্যগুলোতে 'up' ভিন্ন parts of speech: প্রথমটায় adverb (turned-কে modify করছে), তৃতীয়টায় preposition (the road-এর সাথে যুক্ত), চতুর্থটায় adjective (system-কে describe করছে, অর্থ চালু/কার্যকর)।"},{"id":"english-27","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"Which one is a coordinating conjunction?","options":["since","lest","as","so"],"correctIndex":3,"subject":"ইংরেজি","explanation":"'So' একটি coordinating conjunction — সমমানের দুইটি word/phrase/clause যুক্ত করে (and, or, but, yet, so, nor)। বাকি অপশনগুলো (since, lest, as) subordinating conjunction — একটি clause অন্য clause-এর ওপর নির্ভরশীল হলে ব্যবহৃত হয় (how, if, lest, although, as, because, since ইত্যাদি)।"},{"id":"english-28","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"Themes like racial prejudice, oppressive power dynamics, unbridgeable gulf between Eastern & Western cultures, etc. are best exemplified in-","options":["Shadow of the Moon by MM Kaye","Bhowani Junction by John Masters","Kim by Rudyard Kipling","A Passage to India by EM Forster"],"correctIndex":3,"subject":"ইংরেজি","explanation":"E.M. Forster-এর 'A Passage to India' (১৯২৪) racial prejudice, colonial oppressive power dynamics, এবং পূর্ব-পশ্চিমের সাংস্কৃতিক ব্যবধান সবচেয়ে গভীরভাবে তুলে ধরে — Forster-এর বিখ্যাত প্রশ্ন 'Can an Englishman and an Indian be friends?' এবং Marabar Caves-এর ঘটনা এই ভুল বোঝাবুঝির প্রতীক। অন্য অপশনগুলো ভিন্ন মাত্রার: Kipling-এর 'Kim' বরং সাম্রাজ্যবাদকে ইতিবাচকভাবে দেখায়, বাকি দুটি উপন্যাস এই থিমগুলো এত গভীরভাবে explore করে না।"},{"id":"english-29","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Vocabulary","question":"A very large building in which aircraft are housed is called a/an-","options":["terminal","aerodrome","hanger","hangar"],"correctIndex":3,"subject":"ইংরেজি","explanation":"বিমান রাখার বড় ভবনকে 'hangar' (বিমানছাউনি) বলে। খেয়াল করুন বানানে পার্থক্য: 'hanger' (একটি 'e') হলো কাপড় টাঙানোর জিনিস, ভিন্ন শব্দ। 'Terminal' যাত্রীদের জন্য স্টেশন এলাকা, আর 'aerodrome' ছোট বিমান ওঠানামার জায়গা — কোনোটিই বিমান রাখার ভবন নয়।"},{"id":"english-30","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"'You will need a variety of skills, including leadership, endurance etc.' In this sentence the word 'including' is a –","options":["conjunction","gerund","participle","preposition"],"correctIndex":3,"subject":"ইংরেজি","explanation":"এখানে 'including' একটি preposition (participial preposition) — 'সহ/অন্তর্ভুক্ত' অর্থে ব্যবহৃত হয়ে noun phrase-এর আগে বসেছে। concerning, considering, following, excluding, barring-এর মতো participle-জাত শব্দগুলোও একই ধরনের participial preposition হিসেবে কাজ করে।"},{"id":"english-31","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Vocabulary","question":"A synonym of the word 'crepuscular' is-","options":["nocturnal","diurnal","cathemeral","twilit"],"correctIndex":3,"subject":"ইংরেজি","explanation":"'Crepuscular' অর্থ গোধূলিকালীন (গোধূলির মতো, সূর্যাস্তের ঠিক আগের সময় সম্পর্কিত), তাই এর সমার্থক শব্দ 'twilit' (আধোআলোকিত)। বাকিগুলো ভিন্ন অর্থের: nocturnal (নিশাচর/রাতে সক্রিয়), diurnal (দিনে সক্রিয়/আহ্নিক), cathemeral (দিন-রাত অনিয়মিতভাবে সক্রিয়) — এগুলো গোধূলি-নির্দিষ্ট নয়।"},{"id":"english-32","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"'Let me not to the marriage of true minds/Admit impediments; love is not love/Which alters when it alteration finds'. Lines taken from a sonnet by _____.","options":["Spencer","Petrarch","Shakespeare","Donne"],"correctIndex":2,"subject":"ইংরেজি","explanation":"এই লাইনগুলো William Shakespeare-এর 'Sonnet 116' থেকে নেওয়া, যেখানে তিনি সত্যিকারের প্রেমকে সময় বা পরিবর্তনের দ্বারা অবিচল হিসেবে বর্ণনা করেন। Shakespeare মোট ১৫৪টি সনেট ও ৩৭টি নাটক লিখেছেন; তাঁকে Bard of Avon বলা হয়। Shakespearean sonnet সাধারণত তিনটি quatrain ও একটি concluding couplet (ababcdcdefefgg) নিয়ে গঠিত, Iambic Pentameter-এ লেখা।"},{"id":"english-33","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Idioms","question":"The saying 'Every cloud has its silver lining' means:","options":["bad weather is often replaced by good weather","clouds often have shining surroundings","every difficult situation has a more hopeful aspect though not apparent at the beginning","clouds and sunshine go hand in hand"],"correctIndex":2,"subject":"ইংরেজি","explanation":"এই প্রবাদের অর্থ 'মন্দের ভিতরেও মঙ্গল নিহিত আছে' — প্রতিটি কঠিন পরিস্থিতিরই একটি আশাব্যঞ্জক দিক থাকে, যদিও শুরুতে তা বোঝা যায় না। বাকি অপশনগুলো প্রবাদটিকে আক্ষরিকভাবে (আবহাওয়া/মেঘ) ব্যাখ্যা করার চেষ্টা করছে, যেখানে প্রবাদটি রূপক অর্থে ব্যবহৃত হয়।"},{"id":"english-34","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Vocabulary","question":"Identify the incorrect spelling:","options":["diletante","homonym","cromulent","accubation"],"correctIndex":0,"subject":"ইংরেজি","explanation":"সঠিক বানান 'dilettante' (কাব্য/সংগীতের অগভীর অনুরাগী), তাই 'diletante' ভুল বানান। বাকি তিনটি (homonym - সমলেখ শব্দ, cromulent - গ্রহণযোগ্য, accubation - খাবার টেবিলে হেলান দিয়ে বসার অবস্থা) সঠিক বানানেই আছে।"},{"id":"english-35","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"In Gulliver's Travels, which of these traits Swift does not show in his depiction of the land of the Lilliput?","options":["pride","lies","peace & wisdom","silly rules"],"correctIndex":2,"subject":"ইংরেজি","explanation":"Jonathan Swift-এর 'Gulliver's Travels'-এ Lilliput-এর মানুষদের peace ও wisdom দেখানো হয়নি — বরং তারা petty, deceitful, warlike ও তুচ্ছ নিয়মে (যেমন ডিম ভাঙার দিক নিয়ে যুদ্ধ) আচ্ছন্ন। এই ব্যঙ্গাত্মক (satirical) উপন্যাসে Lilliput আসলে ইংল্যান্ডের রাজনীতি-সমাজের প্রতিচ্ছবি, যেখানে pride, lies, ও silly rules প্রকটভাবে দেখানো হয়েছে, কিন্তু শান্তি বা প্রজ্ঞা নয়।"},{"id":"english-36","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"The lines 'A Book of Verses underneath the Bough, A Jug of Wine, a Loaf of Bread -and Thou Beside me singing in the Wilderness...' are taken from a famous translation work by-","options":["Scott Fitzgerald","Edward Fitzgerald","William Fitzgerald","Gerald Fitzgerald"],"correctIndex":1,"subject":"ইংরেজি","explanation":"এই লাইনগুলো Edward FitzGerald-এর 'The Rubaiyat of Omar Khayyam' (১৮৫৯) থেকে নেওয়া — মূলত ফার্সি কবি ওমার খৈয়ামের রচনা থেকে অনুপ্রাণিত হয়ে লেখা, যা ইংরেজি সাহিত্যের একটি ক্লাসিক হিসেবে বিবেচিত। FitzGerald ভিক্টোরিয়ান যুগের লেখক, Trinity College, Cambridge-এ পড়াশোনা করেছেন।"},{"id":"english-37","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"'The villagers believed that he was an honest leader.' Passive form of this sentence is:","options":["He was believed to be an honest leader","He was believed to have been an honest leader","He has been believed to be an honest leader","He was believed he was an honest leader"],"correctIndex":0,"subject":"ইংরেজি","explanation":"that-clause যুক্ত এই ধরনের বাক্যে (believe, think, claim, know, report ইত্যাদি verb সহ) Passive করার সময় personal object-কে subject ধরে 'past participle + to be + ...' গঠন হয়: He was believed to be an honest leader। বাকি অপশনগুলো tense/structure-এ ভুল।"},{"id":"english-38","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"Which play is filled with nonsensical conversations, meaningless dialogues, and characters who often become forgetful?","options":["Pygmalion","The Skin Game","Waiting for Godot","Candida"],"correctIndex":2,"subject":"ইংরেজি","explanation":"Samuel Beckett-এর 'Waiting for Godot' (১৯৫২, Theatre of the Absurd-এর সবচেয়ে বিখ্যাত উদাহরণ) — এতে Vladimir ও Estragon-এর সংলাপ প্রায়ই অর্থহীন ও পুনরাবৃত্তিপ্রবণ, আর চরিত্ররা (বিশেষত Estragon ও Pozzo) প্রায়ই ভুলে যায় কী ঘটেছে। মূলত ফরাসি ভাষায় লেখা (En attendant Godot)-এর নিজের অনুবাদ; ১৯৬৯ সালে Beckett সাহিত্যে নোবেল পুরস্কার পান।"},{"id":"english-39","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Writing","question":"An element required in a paragraph for smooth flow of ideas is called a-","options":["transition sentence","topic sentence","supporting sentence","concluding sentence"],"correctIndex":0,"subject":"ইংরেজি","explanation":"'Transition sentence' প্যারাগ্রাফের মধ্যে বা প্যারাগ্রাফগুলোর মধ্যে ভাবের মসৃণ সংযোগ তৈরি করে (however, therefore, moreover-জাতীয় শব্দ/বাক্য ব্যবহার করে)। এটি topic sentence (মূল বক্তব্য), supporting sentence (উদাহরণ/প্রমাণ দিয়ে সমর্থন), বা concluding sentence (উপসংহার) থেকে আলাদা — এদের কাজ ভিন্ন।"},{"id":"english-40","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"'Poetry is the spontaneous overflow of powerful feeling: it takes its origin from emotion recollected in tranquillity' is a statement ascribed to-","options":["Coleridge","William Wordsworth","TS Eliot","IA Richards"],"correctIndex":1,"subject":"ইংরেজি","explanation":"এই বিখ্যাত উক্তিটি William Wordsworth তাঁর প্রবন্ধ 'Preface to Lyrical Ballads' (১৮০০)-এ করেছেন, যা Romantic criticism-এর ভিত্তিপ্রস্তর হিসেবে বিবেচিত। Wordsworth ও Coleridge-এর যৌথ প্রকাশনা 'Lyrical Ballads' (১৭৯৮, ২৩টি কবিতা, ১৯টি Wordsworth-এর ও ৪টি Coleridge-এর) দিয়ে রোমান্টিক যুগের সূচনা হয়। Wordsworth ১৮৪৩ সালে Poet Laureate হন এবং তাকে Lake Poet ও Poet of Nature বলা হয়।"},{"id":"english-41","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Literature","question":"Which of these works contains a defence of the right of freedom of speech and expression?","options":["Holy Living and Holy Dying","Areopagitica","Religio Medici","A Free Man's Worship"],"correctIndex":1,"subject":"ইংরেজি","explanation":"John Milton-এর 'Areopagitica' (১৬৪৪) মুদ্রণ ও প্রকাশনার স্বাধীনতা রক্ষার জন্য লেখা একটি বিখ্যাত prose pamphlet, যা তৎকালীন Licensing Order (প্রকাশনার আগে সরকারি অনুমতির বাধ্যবাধকতা)-এর বিরুদ্ধে প্রতিবাদ হিসেবে রচিত। বাকি অপশনগুলো ভিন্ন বিষয়ের: Holy Living and Holy Dying (Jeremy Taylor) ধর্মীয় আচরণ নিয়ে, Religio Medici (Thomas Browne) ব্যক্তিগত ধর্মবিশ্বাস নিয়ে, আর A Free Man's Worship (Bertrand Russell) দার্শনিক প্রবন্ধ — কোনোটিই সরাসরি মত প্রকাশের স্বাধীনতার আইনি/রাজনৈতিক পক্ষ সমর্থন করে না।"},{"id":"english-42","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"What gender is the word 'monarch'?","options":["masculine","feminine","neuter","common"],"correctIndex":3,"subject":"ইংরেজি","explanation":"'Monarch' common gender — কারণ এটি পুংবাচক (king) বা স্ত্রীবাচক (queen) উভয়কেই বোঝাতে পারে। এই ধরনের অন্যান্য common gender শব্দ: Parent, Child, Baby, Teacher, Student, Neighbor। Gender চার প্রকার: Masculine, Feminine, Common, ও Neuter (নির্জীব বস্তুর জন্য)।"},{"id":"english-43","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"Which functions both as a transitive and an intransitive verb?","options":["sleep","arrive","break","die"],"correctIndex":2,"subject":"ইংরেজি","explanation":"'Break' উভয়ভাবে ব্যবহৃত হতে পারে — Transitive: 'He broke the window' (object আছে: window); Intransitive: 'The vase broke' (কোনো object নেই)। বাকি অপশনগুলো (sleep, arrive, die) সাধারণত শুধু intransitive verb হিসেবে ব্যবহৃত হয় — এদের পরে সাধারণত object বসে না।"},{"id":"english-44","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Vocabulary","question":"কোনটি সঠিক বানান?","options":["Gazete","Gazzete","Gaggete","Gazette"],"correctIndex":3,"subject":"ইংরেজি","explanation":"সঠিক বানান 'Gazette' (অর্থ: ঘোষণাপত্র, সরকারি ইশতাহার, গেজেট) — সরকারি সিদ্ধান্ত, প্রজ্ঞাপন ও আইনি নোটিশ প্রকাশের মাধ্যম হিসেবে ব্যবহৃত হয়। বাকি অপশনগুলো ভুল বানান।"},{"id":"english-45","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Idioms","question":"'To have a shot' means:","options":["to open fire","to take a photograph","to make a try","to test a gun"],"correctIndex":2,"explanation":"'To have a shot' is an idiom meaning to attempt or try something, often with an element of risk or uncertainty involved — it does not literally refer to firing a weapon or taking a photograph. For example: 'I've never done this before, but I'll have a shot at it.'","subject":"English"},{"id":"english-46","exam":"৫০তম বিসিএস প্রিলিমিনারি পরীক্ষা","topic":"Grammar","question":"Identify the compound sentence:","options":["Either you do it or you will be fined","Unless you do it, you will be fined","Do it or I shall fine you","You have to do it, otherwise I will fine you"],"correctIndex":2,"explanation":"বাংলাদেশ সরকারি কর্ম কমিশনের (পিএসসি) প্রকাশিত মূল উত্তরমালায় এই প্রশ্নটি একটি বিতর্কিত/ত্রুটিপূর্ণ প্রশ্ন হিসেবে চিহ্নিত হয়েছিল, কারণ প্রদত্ত অপশনগুলোর মধ্যে দুটি — 'Either you do it or you will be fined' এবং 'Do it or I shall fine you' — উভয়ই ব্যাকরণগতভাবে compound sentence-এর বৈধ উদাহরণ (দুটি independent clause সমন্বয়কারী conjunction দিয়ে যুক্ত)। তবে Traditional Grammar অনুযায়ী 'Do it or I shall fine you' গঠনটি অধিকতর প্রচলিত ও গ্রহণযোগ্য বলে বিবেচিত হয়, তাই এটিকেই এখানে সঠিক উত্তর হিসেবে দেখানো হলো। অন্যদিকে, 'Unless you do it, you will be fined' একটি complex sentence (unless একটি subordinating conjunction), আর 'You have to do it, otherwise I will fine you' বাক্যে 'otherwise' কোনো conjunction নয় বলে এটি প্রথাগত ব্যাকরণ অনুযায়ী ভুল বাক্য হিসেবে গণ্য হয়।","subject":"English"},{"id":"english-47","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"General Knowledge","question":"A rocket flying to the moon does not need wings because-","options":["it has no engine","space has too much dust","it has no fuel","space is airless"],"correctIndex":3,"explanation":"Space is airless, so there's no air for wings to push against — rockets rely on thrust instead."},{"id":"english-48","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Vocabulary","question":"Rubber is notable for its-","options":["lightness","heaviness","elasticity","Viscosity"],"correctIndex":2,"explanation":"Rubber stretches and snaps back — that property is elasticity."},{"id":"english-49","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"General Knowledge","question":"Julius Caesar was the ruler of Rome about-","options":["1000 years ago","1500 years ago","2000 years ago","3000 years ago"],"correctIndex":2,"explanation":"Caesar died in 44 BC, roughly 2000 years ago."},{"id":"english-50","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"General Knowledge","question":"The South Pole is located in the-","options":["Arctic","Antarctic","Antipodes","Occident"],"correctIndex":1,"explanation":"The South Pole sits within Antarctica — not the Arctic, which is the North Pole's region."},{"id":"english-51","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Analogy","question":"Tiger : Zoology :: Mars : ?","options":["Astrology","Cryptology","Astronomy","Telescope"],"correctIndex":2,"explanation":"Zoology studies tigers; astronomy studies Mars — same 'field of study' relationship."},{"id":"english-52","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Analogy","question":"Break : Repair : : Wound : ?","options":["Heal","Hurt","Fix","Plaster"],"correctIndex":0,"explanation":"Repair fixes something broken; heal fixes a wound — same restorative relationship."},{"id":"english-53","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Analogy","question":"Frightened : Scream : : Angry : ?","options":["Cry","Shiver","Shout","Sneer"],"correctIndex":2,"explanation":"Fright triggers a scream; anger typically triggers a shout."},{"id":"english-54","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Fill in the blanks","question":"He ____ consciousness as a result of his head hitting the car's dashboard.","options":["failed","broke","lost","Passed"],"correctIndex":2,"explanation":"'Lost consciousness' is the standard collocation for fainting — not 'failed' or 'broke'."},{"id":"english-55","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Grammar","question":"Only after I ____ home, did I remember my doctor's appointment.","options":["going","go","went","gone"],"correctIndex":2,"explanation":"'Only after' at the start forces simple past tense — 'went', not 'go/going'."},{"id":"english-56","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Fill in the blanks","question":"When they had their first child, they put ____ a large sum for his education.","options":["aside","beside","outside","Under"],"correctIndex":0,"explanation":"'Put aside' means to save money for later — 'beside/outside' don't fit this meaning."},{"id":"english-57","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Preposition","question":"Julia has been ill ____ three months.","options":["since","about","in","for"],"correctIndex":3,"explanation":"'For' pairs with duration (three months); 'since' pairs with a starting point."},{"id":"english-58","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Grammar","question":"We were waiting for the bus. The underlined part is-","options":["a noun phrase","an infinitive phrase","a prepositional phrase","a verb phrase"],"correctIndex":2,"explanation":"'For the bus' starts with a preposition + noun — a prepositional phrase."},{"id":"english-59","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Vocabulary","question":"The word 'disinterested' means-","options":["lack of interest","indifferent","callous","neutral"],"correctIndex":3,"explanation":"'Disinterested' means neutral/impartial — often confused with 'uninterested' (lacking interest)."},{"id":"english-60","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Literature","question":"Who did write first English dictionary?","options":["Boswell","Ben Jonson","Samuel Johnson","Milton"],"correctIndex":2,"explanation":"Samuel Johnson compiled the first major English dictionary (1755)."},{"id":"english-61","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Vocabulary","question":"New programs will be ____ next week in Bangladesh Television.","options":["telecast","published","telecasted","Broadecasted"],"correctIndex":0,"explanation":"'Telecast' stays the same in base and past-participle form, like 'broadcast' — not 'telecasted'."},{"id":"english-62","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Vocabulary","question":"The word 'electorate' means-","options":["election office","a body of voters","many elections","Candidates"],"correctIndex":1,"explanation":"'Electorate' means the entire body of eligible voters."},{"id":"english-63","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Literature","question":"'Animal Farm' was written by-","options":["George Orwell","Stevenson","Swift","Mark Twain"],"correctIndex":0,"explanation":"George Orwell wrote 'Animal Farm' (1945), a political allegory using farm animals."},{"id":"english-64","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Preposition","question":"There is no alternative ____ training.","options":["to","for","than","of"],"correctIndex":0,"explanation":"Fixed expression: 'alternative to' something — not 'for' or 'than'."},{"id":"english-65","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Grammar","question":"Which sentence is correct?","options":["This is an unique case","This is a unique case","This is a very unique case","This is the most unique case"],"correctIndex":1,"explanation":"'Unique' starts with a consonant sound (/j/), so it takes 'a' — and shouldn't be modified by 'very/most'."},{"id":"english-66","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Vocabulary","question":"I cannot ____ to pay such high prices.","options":["able","but","try","afford"],"correctIndex":3,"explanation":"'Afford' means having enough money for something — fits 'pay high prices'."},{"id":"english-67","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Grammar","question":"Dhaka is becoming one of the ____ cities in Asia.","options":["more busy","busy","busiest","most busiest"],"correctIndex":2,"explanation":"'One of the + superlative': 'busiest', not 'more busy' or the double superlative 'most busiest'."},{"id":"english-68","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Grammar","question":"He had written the book before he-","options":["retired","had retired","has retired","will be retired"],"correctIndex":0,"explanation":"'Had written' marks the earlier action; the later one takes simple past — 'retired'."},{"id":"english-69","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Preposition","question":"Rizvi requested Rini ____ telephone to attend the meeting.","options":["over","through","with","by"],"correctIndex":3,"explanation":"Fixed expression: 'by telephone' — the means of communication."},{"id":"english-70","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Vocabulary","question":"The word 'precedence' means-","options":["example","priority","elderly","case"],"correctIndex":1,"explanation":"'Precedence' means priority or rank — easily confused with 'precedent' (an earlier example)."},{"id":"english-71","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Grammar","question":"The prices of rice are-","options":["raising","risen","rising","Raised"],"correctIndex":2,"explanation":"Prices rise on their own (intransitive) — 'raise' needs an object, so 'rising' is correct."},{"id":"english-72","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Idioms","question":"'To get along with' means-","options":["to adjust","to accompany","to interest","to walk"],"correctIndex":0,"explanation":"'Get along with' means to adjust well and stay in harmony with someone."},{"id":"english-73","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Literature","question":"'If winter comes, can spring be far behind?' These lines were written by-","options":["Keats","Frost","Eliot","Shelley"],"correctIndex":3,"explanation":"Shelley closes 'Ode to the West Wind' (1819) with this line — often misattributed to Keats."},{"id":"english-74","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Vocabulary","question":"The verb of the word 'short' is-","options":["enshort","shorten","shorted","shorting"],"correctIndex":1,"explanation":"'Short' becomes 'shorten' — the common '-en' pattern for adjective-to-verb (like 'widen')."},{"id":"english-75","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Analogy","question":"'light' is to 'dark' as 'cold' is to-","options":["hot","heat","cool","Winter"],"correctIndex":0,"explanation":"Light↔dark is a direct opposite pair; cold↔hot completes the same pattern."},{"id":"english-76","exam":"২৮তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"English","topic":"Preposition","question":"Many prefer donating money ____ distributing clothes.","options":["than","but","to","Without"],"correctIndex":2,"explanation":"Fixed structure: 'prefer X to Y' — not 'than' or 'without'."},{"id":"english-77","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"AMICABLE (Synonym)","options":["Interesting","Loving","Affectionate","Friendly"],"correctIndex":3,"explanation":"AMICABLE means characterized by friendliness and goodwill; the closest synonym here is 'Friendly'."},{"id":"english-78","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Opposite word for LIABILITY:","options":["Treasure","Debt","Assets","Property"],"correctIndex":2,"explanation":"LIABILITY refers to a debt or financial obligation, so its opposite is 'Assets' — resources of value owned rather than owed."},{"id":"english-79","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Opposite word for HATE:","options":["Admire","Abhor","Concern","Loathe"],"correctIndex":0,"explanation":"HATE means to dislike intensely; its opposite is 'Admire', which expresses positive regard or esteem."},{"id":"english-80","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"A song embodying religious and sacred emotions _____.","options":["Lyric","Ode","Hymn","Ballad"],"correctIndex":2,"explanation":"A 'Hymn' is specifically a song of praise or worship expressing religious and sacred devotion, unlike a Lyric, Ode, or Ballad which are broader poetic/song forms."},{"id":"english-81","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Time after twilight and before night —","options":["Evening","Dawn","Dusk","Eclipse"],"correctIndex":2,"explanation":"'Dusk' refers to the darkening period just after twilight and just before full night sets in."},{"id":"english-82","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Parliamentary democracy demands discipline and _____ to the rules.","options":["adherence","respectful","knowledge","awareness"],"correctIndex":0,"explanation":"'Adherence' (noun, meaning strict compliance) correctly follows 'demands discipline and ___ to the rules', matching the required grammatical form."},{"id":"english-83","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Reason is the highest faculty ______ on human by their creator.","options":["entrusted","endowed","bestowed","conferred"],"correctIndex":2,"explanation":"'Bestowed on' is the idiomatically correct collocation meaning 'given as a gift/quality', matching the sentence's structure 'X is bestowed on Y by Z'."},{"id":"english-84","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Rishan walks as if he ____ lame.","options":["is","had been","has","were"],"correctIndex":3,"explanation":"In a hypothetical/unreal comparison introduced by 'as if', the subjunctive mood requires 'were' regardless of subject number."},{"id":"english-85","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"One of the four sentences given is grammatically wrong: (Neither you nor I am in a sound position / Laziness is detrimental for success / He begged the favour of my granting him leave / Your action is not in conformity with the law)","options":["Neither you nor I am in a sound position.","Laziness is detrimental for success.","He begged the favour of my granting him leave.","Your action is not in conformity with the law."],"correctIndex":1,"explanation":"The correct preposition after 'detrimental' is 'to', not 'for' — the sentence should read 'Laziness is detrimental to success', making this the grammatically wrong option."},{"id":"english-86","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"One of the four sentences given is grammatically wrong: (He has no desire for fame / I intend going to Rajshahi / He is too miserly to part with his money / He has invited me for dinner)","options":["He has no desire for fame.","I intend going to Rajshahi.","He is too miserly to part with his money.","He has invited me for dinner."],"correctIndex":1,"explanation":"'Intend' is conventionally followed by a to-infinitive ('intend to go'), not a gerund, so 'I intend going to Rajshahi' is the grammatically incorrect sentence."},{"id":"english-87","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Each of the following idioms is followed by some alternative — Choose the one which best expresses its meaning: To keep one's head —","options":["to save oneself","to be self respectful","to keep calm","none of these"],"correctIndex":2,"explanation":"The idiom 'to keep one's head' means to remain calm and composed, especially under pressure or in a crisis."},{"id":"english-88","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"To put the cart before the horse —","options":["to offer a person what he cannot eat","to force a person to do something","to raise obstacle","to reverse the natural order of things"],"correctIndex":3,"explanation":"This idiom means doing things in the wrong order — reversing the natural or logical sequence of actions."},{"id":"english-89","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"To read between the lines —","options":["to concentrate","to suspect","to read carefully","to grasp the hidden meaning"],"correctIndex":3,"explanation":"This idiom means to understand an implied or hidden meaning that is not directly stated in the text."},{"id":"english-90","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"In each of the following questions, a sentence has been given in Active (or Passive) voice. Select the one which best expresses the same sentence in Passive (or Active) voice: I know him.","options":["He is known by me.","He was known to me.","He has been known by me.","He is known to me."],"correctIndex":3,"explanation":"The verb 'know' in the passive voice conventionally takes the preposition 'to' rather than 'by' — so 'I know him' becomes 'He is known to me.'"},{"id":"english-91","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"A lion may be helped even by a little mouse.","options":["A little mouse may even help a lion.","Even a little mouse may help a lion.","A little mouse can even help a lion.","Even a little mouse ought to help a lion."],"correctIndex":1,"explanation":"Converting the passive sentence to active voice while preserving 'even' as emphasis on the subject gives: 'Even a little mouse may help a lion.'"},{"id":"english-92","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Choose the correctly spelt word:-","options":["Liesure","Leisure","Leasure","Lesiure"],"correctIndex":1,"explanation":"The correct spelling is 'Leisure' — commonly misspelled due to the tricky 'ei' vowel combination (an exception to the usual 'i before e' rule)."},{"id":"english-93","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Choose the correctly spelt word:-","options":["Superceed","Superseed","Supercede","Supersede"],"correctIndex":3,"explanation":"The correct spelling is 'Supersede' — one of the few English words ending in '-sede' rather than the more common '-cede' or '-ceed'."},{"id":"english-94","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"Of the four alternatives given under the sentence, find the one that best fits into the blank space: The horror movie scared them out of their ______.","options":["wits","seats","lives","funds"],"correctIndex":0,"explanation":"The idiom 'scared out of one's wits' means to frighten someone severely, which fits the context of a horror movie."},{"id":"english-95","exam":"৩০তম বিসিএস","subject":"ইংরেজি","question":"The people who carry a coffin at a funeral are called ________.","options":["undertakers","supporters","pallbearers","Mourners"],"correctIndex":2,"explanation":"People who carry a coffin at a funeral are specifically called 'pallbearers', distinct from 'undertakers' (who arrange funerals) and 'mourners' (who grieve)."},{"id":"english-96","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"Choose the correct synonym for 'Extempore'-","options":["Planned","Improvise","Impromptu","Immediate"],"correctIndex":2,"explanation":"'Extempore' means spoken or done without preparation. 'Impromptu' carries the same meaning — done on the spur of the moment, without prior planning. 'Planned' is its opposite, while 'Improvise' is a verb (to make up on the spot) rather than a matching adjective, and 'Immediate' relates to time, not lack of preparation."},{"id":"english-97","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"What is the most appropriate synonym of the word 'Menacing' from the options below:","options":["Encouraging","Alarming","Promising","Auspicious"],"correctIndex":1,"explanation":"'Menacing' means threatening or likely to cause harm. 'Alarming' shares this sense of causing fear or concern. The other options — Encouraging, Promising, and Auspicious — all carry positive connotations, opposite to the threatening sense of 'Menacing'."},{"id":"english-98","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"Choose the correct antonym for 'Oblige'-","options":["Bind","Require","Bother","Censure"],"correctIndex":2,"explanation":"'Oblige' means to do a favour for someone or to help/please them. 'Bother' (to trouble or inconvenience someone) is its opposite. 'Bind' and 'Require' are closer in meaning to obligation itself, and 'Censure' means to criticize harshly, which is not a direct opposite of obliging someone."},{"id":"english-99","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"'Cynical'","options":["Pessimistic","Gullible","Equivocal","Liberal"],"correctIndex":1,"explanation":"'Cynical' describes someone distrustful of others' sincerity or motives. Its antonym, asked for here, is 'Gullible' — easily trusting or deceived. 'Pessimistic' is actually close in meaning to cynical rather than opposite; 'Equivocal' means ambiguous, and 'Liberal' relates to open-mindedness, neither of which is the precise antonym."},{"id":"english-100","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Sentence Correction","question":"Select the alternative which best expresses the meaning of the given sentence: \"We were no more surprised than Rahman\".","options":["We were less surprised than Rahman.","We were all surprised.","Rahman was less surprised than us.","We were as surprised as Rahman."],"correctIndex":3,"explanation":"The structure 'no more...than' expresses equality, not inequality — it means the two things being compared are the same in degree. So 'We were no more surprised than Rahman' means both were equally surprised, i.e., 'We were as surprised as Rahman.'"},{"id":"english-101","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Sentence Correction","question":"Not once has our neighbour invited us into his house.","options":["Our neighbour has invited us into his house not once but many times.","Our neighbour has never invited us into his house.","Occasionally our neighbour has invited us into his house.","Our neighbour has not always invited us into his house."],"correctIndex":1,"explanation":"'Not once' means zero times, i.e., never. So 'Not once has our neighbour invited us into his house' is equivalent to 'Our neighbour has never invited us into his house.' The other options wrongly suggest invitations did happen, either occasionally or repeatedly."},{"id":"english-102","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Grammar","question":"Choose a suitable word/phrase to fill in the blanks of the given sentence : Travellers ____ their reservation well in advance if they want to visit the St. Martin's island.","options":["had better to get","had to better get","had better get","had better got"],"correctIndex":2,"explanation":"The idiomatic modal expression 'had better' is followed directly by the base form of the verb, without 'to' — so the correct form is 'had better get'. 'had better to get' and 'had to better get' are grammatically wrong constructions, and 'had better got' incorrectly uses the past participle instead of the base verb."},{"id":"english-103","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Grammar","question":"After food has been dried or canned ____ for later consumption.","options":["it should be stored","That it should be stored","should be stored","which should be stored"],"correctIndex":0,"explanation":"After food has been dried or canned একটি সময়বাচক অধীন খণ্ডবাক্য (subordinate clause); এর পরে মূল বাক্যাংশের নিজস্ব কর্তা (subject) লাগে, তাই 'it should be stored' সঠিক। 'should be stored' একা হলে কর্তা থাকে না; 'That it should be stored' ও 'which should be stored' বসালে বাক্যটি অসম্পূর্ণ খণ্ডে পরিণত হয়।"},{"id":"english-104","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"Choose the word/phrase that best retains the meaning of the underlined word/phrase in the given sentence: Despite being a brilliant scientist, he does not seem to \"get his ideas across\".","options":["make his ideas understood","get his ideas down pat","summarise his ideas","put together his ideas"],"correctIndex":0,"explanation":"The idiom 'get one's ideas across' means to successfully communicate one's ideas so that others understand them. This matches 'make his ideas understood'. 'get ideas down pat' means to master something perfectly, 'summarise' means to shorten, and 'put together' means to compile or organise — none of which capture the sense of successful communication."},{"id":"english-105","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"What may be considered \"courteous\" in one culture may be arrogant in another.","options":["flimsy","coarse","gracious","Friendly"],"correctIndex":2,"explanation":"'Courteous' means polite and respectful in manner. 'Gracious' conveys a similar sense of polite, kind and considerate behaviour, making it the closest synonym among the options. 'Flimsy' means weak/insubstantial, 'coarse' means rough or vulgar, and while 'Friendly' is positive, it does not specifically capture the sense of polished politeness that 'courteous' conveys."},{"id":"english-106","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Grammar","question":"Identify the incorrect word/phrase indicated by (1), (2), (3) or (4) in the following sentence: \"Every\" man or woman \"should\" vote \"for\" the candidate of \"their\" choice.","options":["Every (1)","should (2)","for (3)","their (4)"],"correctIndex":3,"explanation":"'Every man or woman' is a singular antecedent (referring to one person at a time), so it must be followed by a singular pronoun such as 'his or her', not the plural 'their'. Hence the error lies in the word 'their', marked (4)."},{"id":"english-107","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Grammar","question":"Identify the incorrect word/phrase indicated by (1), (2), (3) or (4) in the following sentence: A doctor may be able \"to diagnose\" a problem \"prefect\" but he may not able to find a drug \"to which\" the patient \"will respond\".","options":["to diagnose (1)","perfect (2)","to which (3)","will respond (4)"],"correctIndex":1,"explanation":"বাক্যে 'prefect' (স্কুলের শৃঙ্খলা-দায়িত্বপ্রাপ্ত শিক্ষার্থী, বিশেষ্য) অর্থ ও ব্যাকরণ—দুদিক থেকেই বেমানান। 'diagnose' ক্রিয়াকে বিশেষিত করতে ক্রিয়াবিশেষণ 'perfectly' দরকার, তাই (2) ভুল। 'to diagnose' (able to-এর পর infinitive), 'to which' ও 'will respond' বাক্যে চলে।"},{"id":"english-108","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Grammar","question":"Identify the incorrect word/phrase indicated by (1), (2), (3) or (4) in the following sentence: According to experts a good way \"to\" \"improve\" listening skills is \"by\" \"watch\" television, specially news and documentaries.","options":["to (1)","improve (2)","by (3)","watch (4)"],"correctIndex":3,"explanation":"After the preposition 'by', a verb must take the gerund (-ing) form, so 'watch' should be 'watching'. The error is therefore at position (4)."},{"id":"english-109","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"Choose the pair of words that expresses a relationship similar to that of the given pair: Words:writer","options":["Laws : policeman","Butter : baker","Chalk : black board","Joy : emotion"],"correctIndex":1,"explanation":"প্রশ্নটি কিছুটা অস্পষ্ট, তাই উত্তর সোর্সের উত্তর-সূত্র অনুযায়ী। সম্ভাব্য সম্পর্ক: পেশাজীবী ও তার কাজের উপকরণ — লেখকের উপকরণ শব্দ (Words : writer), বেকারের উপকরণ মাখন (Butter : baker)। Chalk : black board উপকরণ ও পৃষ্ঠের সম্পর্ক, Joy : emotion উপশ্রেণি ও শ্রেণির, আর Laws : policeman-এ পুলিশ আইন প্রয়োগ করে, তৈরি বা ব্যবহার করে না।"},{"id":"english-110","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"Choose the pair of words that expresses a relationship similar to that of the given pair: Patron:support","options":["spouse : divorce","Artist : imitation","Counselor : advice","Restaurant : customer"],"correctIndex":2,"explanation":"A patron provides support as their defining function. Similarly, a counselor provides advice as their defining function — the relationship is 'a role and the characteristic action associated with it', matching Counselor:advice."},{"id":"english-111","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"Choose the pair of words that expresses a relationship similar to that of the given pair: Heart : human","options":["Wall : brick","Hand : child","Kitchen : house","Engine : car"],"correctIndex":3,"explanation":"The heart is the essential functioning component that powers/drives a human body. Similarly, the engine is the essential functioning component that powers/drives a car — matching the 'vital part : whole system' relationship, which fits Engine:car."},{"id":"english-112","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"Choose the meaning of the given expressions: \"No news is good news\"","options":["It is likely that we expect bad news.","It is likely to have bad news.","It is likely that nothing bad has happened.","It is unlikely that nothing bad has happened."],"correctIndex":2,"explanation":"This common English proverb means that if no information/news has arrived about a situation, it is reasonable to assume nothing bad has happened — because bad news tends to travel and reach people quickly, whereas the absence of news suggests things are fine."},{"id":"english-113","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"A bird in hand is worth two in the bush.","options":["Take what you have got readily available rather than expecting better in the future.","The seen is better than the unseen.","Promises are better than actuals.","It is no good beating about the bush."],"correctIndex":0,"explanation":"This well-known proverb advises that it is wiser to keep hold of something certain and available now, rather than risk losing it while chasing a possibly better but uncertain opportunity — best captured by 'Take what you have got readily available rather than expecting better in the future.'"},{"id":"english-114","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Vocabulary","question":"The sentence 'Who would have thought Shylock was so unkind' expresses-","options":["hyperbole","interrogation","command","wonder"],"correctIndex":3,"explanation":"Although the sentence is structured as a question, it is not literally asking for information; it is expressing astonishment or surprise (wonder) at Shylock's unkindness — a rhetorical use of question form to convey emotion rather than seek an answer."},{"id":"english-115","exam":"৩২তম বিসিএস প্রিলিমিনারি পরীক্ষা","subject":"ইংরেজি","topic":"Idioms & Phrases","question":"To 'raise one's brows' indicate-","options":["annoyance","disapproval","indifference","surprise"],"correctIndex":3,"explanation":"The idiom/gesture 'raise one's brows (eyebrows)' is commonly used to express surprise or mild astonishment at something unexpected. It is not primarily associated with annoyance, disapproval, or indifference, though context can occasionally shade its meaning; the core sense remains surprise."},{"id":"english-116","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Preposition","question":"Pick appropriate preposition for the following sentence: Noureen will discuss the issue with Nasir ____ phone.","options":["in","over","by","On"],"correctIndex":2,"explanation":"যোগাযোগের মাধ্যম বোঝাতে 'by' বসে এবং তখন 'the' ছাড়া noun আসে: by phone, by post, by e-mail। বাক্যে phone-এর আগে 'the' নেই, তাই ব্যাকরণগত দিক থেকে 'by phone' সঠিক। 'over/on the phone' বলতে 'the' লাগত। সতর্কতা: কিছু উৎস ও গাইডে এই প্রশ্নের উত্তর 'over' দেওয়া আছে; ৩৩তম বিসিএসের সরকারি উত্তর-কী নিয়ে উৎসগুলোর মধ্যে অমিল আছে।"},{"id":"english-117","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Preposition","question":"Put the appropriate preposition for the sentence below : Some writers sink ____ oblivion in course of time.","options":["on","from","under","into"],"correctIndex":3,"explanation":"'sink into oblivion' একটি প্রচলিত প্রয়োগ — 'into' গতির অভিমুখ বোঝায় (তলিয়ে গিয়ে বিস্মৃতিতে পৌঁছানো)। on/from/under বসালে অর্থ ও প্রয়োগ দুটোই ঠিক থাকে না।"},{"id":"english-118","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Idioms","question":"'Call to mind' means-","options":["fantasize","attend","remember","Request"],"correctIndex":2,"explanation":"'Call to mind' = remember/recall, অর্থাৎ মনে করা বা স্মরণ করা। fantasize (কল্পনা করা), attend (যোগ দেওয়া/মনোযোগ দেওয়া) এবং request (অনুরোধ করা) — কোনোটিই 'মনে পড়া' নয়।"},{"id":"english-119","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Idioms","question":"'Pass away' means-","options":["disappear","die","erase","Fall"],"correctIndex":1,"explanation":"'Pass away' = die — মৃত্যুকে সৌজন্যমূলকভাবে বলার প্রচলিত বাক্যাংশ (euphemism)। disappear (অদৃশ্য হওয়া), erase (মুছে ফেলা) বা fall (পড়ে যাওয়া) মৃত্যুর অর্থ দেয় না।"},{"id":"english-120","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"Pick the word that is synonymous with 'authoritarian'.","options":["autocratic","senior","elderly","Potential"],"correctIndex":0,"explanation":"'Authoritarian' = কর্তৃত্ববাদী, কঠোরভাবে আদেশ মানতে বাধ্য করা; সমার্থক 'autocratic'। senior ও elderly বয়স বা পদমর্যাদা বোঝায়, potential মানে সম্ভাবনাময় — কোনোটিই কর্তৃত্ববাদী নয়।"},{"id":"english-121","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"The word 'permissive' implies-","options":["humble","law-abiding","liberal","Submissive"],"correctIndex":2,"explanation":"'Permissive' = যে সহজে অনুমতি দেয়, উদার/শিথিল; নিকটতম 'liberal'। humble (বিনয়ী), law-abiding (আইন মান্যকারী) ও submissive (বশ্য) — কোনোটিই 'অনুমতিদানকারী' অর্থ দেয় না।"},{"id":"english-122","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"Pick the correct part to fill in the gap of the following sentence : Each of the sons followed- father's trade.","options":["their","her","whose","his"],"correctIndex":3,"explanation":"'Each of' এর পর পুরুষবাচক বহুবচন noun থাকলেও pronoun একবচন ও পুরুষবাচক হয় — sons পুরুষ, তাই 'his'। 'their' বহুবচন হওয়ায় Each-এর সঙ্গে মেলে না, 'her' স্ত্রীলিঙ্গ, আর 'whose' relative pronoun — এখানে বসে না।"},{"id":"english-123","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"'Subject-Verb Agreement' refers to-","options":["person only","number, person and gender","number and person","number only"],"correctIndex":2,"explanation":"Subject-verb agreement বলতে verb-এর সঙ্গে subject-এর number (একবচন/বহুবচন) ও person (১ম/২য়/৩য় পুরুষ) মিল বোঝায়। ইংরেজি verb form-এ gender কোনো ভূমিকা রাখে না, তাই 'gender' যুক্ত অপশন ভুল; 'person only' বা 'number only' অসম্পূর্ণ।"},{"id":"english-124","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Sentence Correction","question":"The only error in the sentence '' One of the recommendation made by the committee was accepted by the authorities'' is-","options":["recommendation","was","accepted by","Committee"],"correctIndex":0,"explanation":"'One of the ...' গঠনের পর noun বহুবচন হয়, তাই 'recommendation' ভুল, হবে 'recommendations'। verb 'was' ঠিক, কারণ subject 'One' একবচন। 'accepted by' ও 'committee' — দুটোতেই কোনো ভুল নেই।"},{"id":"english-125","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"'The French' refers to-","options":["the French people","the French language","the French manners","the French society"],"correctIndex":0,"explanation":"'the + জাতীয়তাবাচক adjective' (the French, the British) সমগ্র জাতির মানুষকে (people) বোঝায়। ভাষা বোঝাতে 'the' ছাড়া French বা 'the French language' বলতে হয়; manners বা society নয়।"},{"id":"english-126","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"If a person cannot stop taking drugs, he or she is-","options":["attached to them","committed to them","addicted to them","devoted to them"],"correctIndex":2,"explanation":"যে মাদক ছাড়তে পারে না, তাকে 'addicted to' বলে। attached to = মমতায় যুক্ত, committed to = প্রতিশ্রুতিবদ্ধ, devoted to = নিবেদিত — এগুলো ইতিবাচক বন্ধন বোঝায়, নেশার আসক্তি নয়।"},{"id":"english-127","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"The word 'officialese' means-","options":["plural number of official","language used in offices","plural number of office","vague expressions"],"correctIndex":1,"explanation":"'Officialese' = সরকারি/দাপ্তরিক কাজে ব্যবহৃত জটিল ও কেতাদুরস্ত ভাষা, অর্থাৎ language used in offices। এটি 'official' বা 'office'-এর বহুবচন নয়, আর vague expression-ও এর সঠিক সংজ্ঞা নয়।"},{"id":"english-128","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"The verb 'succumb' means-","options":["achieve","submit","win","Conquer"],"correctIndex":1,"explanation":"'Succumb' = কারও/কিছুর কাছে হার মানা, আত্মসমর্পণ করা — সমার্থক 'submit' (যেমন: succumb to pressure)। achieve, win ও conquer জয় বা অর্জনের অর্থ দেয়, যা succumb-এর উল্টো।"},{"id":"english-129","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"Fill in the blank with the appropriate part: We look forward ____ a response from you.","options":["to receiving","to receive","in receiving","for receiving"],"correctIndex":0,"explanation":"'look forward to' বাক্যাংশের 'to' একটি preposition, infinitive marker নয়; preposition-এর পর verb থাকলে তা -ing রূপে (gerund) বসে। তাই 'to receiving'। 'to receive' infinitive, আর 'in/for receiving' প্রয়োগে 'look forward' বাক্যাংশ ভেঙে যায়।"},{"id":"english-130","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"If a part of a speech or speech or writing breaks the theme, it is called-","options":["pomposity","digression","exaggeration","Anti-climax"],"correctIndex":1,"explanation":"বক্তৃতা বা লেখায় মূল বিষয় থেকে সরে গিয়ে অপ্রাসঙ্গিক কিছু বলাকে 'digression' বলে। pomposity = আড়ম্বরপূর্ণ ভাষা, exaggeration = অতিরঞ্জন, anti-climax = চরম মুহূর্তের পর হঠাৎ গুরুত্বহীন কিছু — কোনোটিই মূল সুর থেকে সরে যাওয়া নয়।"},{"id":"english-131","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Idioms","question":"The expression 'take into account' means-","options":["count numbers","consider","think seriously","Asses"],"correctIndex":1,"explanation":"'Take into account' = consider, অর্থাৎ বিবেচনায় নেওয়া। 'count numbers' আক্ষরিক গণনা, আর 'think seriously' ও 'assess' (মূল্যায়ন করা) কাছাকাছি হলেও ঠিক বিবেচনায় নেওয়ার অর্থ দেয় না।"},{"id":"english-132","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Idioms","question":"Choose the best translation of 'কর্তৃপক্ষ তাকে তিরস্কার করলো' from the alternatives below-","options":["The authorities criticised him.","The authorities took him to book.","The authorities gavereins to him.","The authorities took him to task."],"correctIndex":3,"explanation":"'Take (someone) to task' = কাউকে তিরস্কার করা বা তার কাজের জন্য ভর্ৎসনা করা। 'took him to book' রূপে কোনো প্রচলিত idiom নেই ('bring to book' ভিন্ন idiom), 'give reins to' মানে স্বাধীনতা দেওয়া, আর 'criticised' সাধারণ সমালোচনা বোঝায়।"},{"id":"english-133","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Vocabulary","question":"''Such claim needs to be tested empirically'' suggest that-","options":["The test should be based on assumption.","The test should be based on idea.","The test should be based on experience.","The test should be based on calculation."],"correctIndex":2,"explanation":"'Empirically' মানে অভিজ্ঞতা বা পর্যবেক্ষণ ও পরীক্ষার ভিত্তিতে। অতএব দাবি empirically যাচাই করা মানে অভিজ্ঞতা/প্রমাণের ভিত্তিতে যাচাই। assumption (অনুমান), idea (ধারণা) ও calculation (হিসাব) empirical বলতে যা বোঝায় তা নয়।"},{"id":"english-134","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Idioms","question":"The idiom ''put up with'' means-","options":["stay together","tolerate","keep trust","Protect"],"correctIndex":1,"explanation":"'Put up with' = tolerate, অর্থাৎ সহ্য করা বা মেনে নেওয়া। stay together (একসাথে থাকা), keep trust (বিশ্বাস রাখা) ও protect (রক্ষা করা) এই idiom-এর অর্থ নয়।"},{"id":"english-135","exam":"৩৩তম বিসিএস","subject":"ইংরেজি","topic":"Grammar","question":"In many ways, riding a bicycle is similar to-","options":["driving a car","when one drives a car","the driving of a car","when we drive a car"],"correctIndex":0,"explanation":"তুলনা করার সময় দুই অংশের গঠন একই রকম (parallel) হতে হয়। 'riding a bicycle' gerund, তাই তুলনার অপর অংশেও gerund — 'driving a car' — বসে। বাকি বিকল্পে 'when one drives' ইত্যাদি clause বা 'the driving of' গঠন আসায় সমান্তরালতা নষ্ট হয়।"}];
